const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C={ink:'#17384a',blue:'#407ea3',cyan:'#60bfce',gold:'#e9b655',silicon:'#a8bac5',resist:'#d88072',green:'#66a897',pale:'#edf4f5'};
const rect=(x,y,w,h,f=C.silicon,rx=3)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}" stroke="${C.ink}" stroke-width="1.5"/>`;
const circle=(x,y,r,f=C.cyan)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" stroke="${C.ink}" stroke-width="1.4"/>`;
const line=(x,y,a,b,color=C.ink,width=2)=>`<line x1="${x}" y1="${y}" x2="${a}" y2="${b}" stroke="${color}" stroke-width="${width}"/>`;
const path=(d,fill='none',stroke=C.ink,width=2)=>`<path d="${d}" fill="${fill}" stroke="${stroke}" stroke-width="${width}"/>`;
const text=(x,y,t,size=13,fill=C.ink,anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" font-family="system-ui, sans-serif" fill="${fill}" text-anchor="${anchor}">${esc(t)}</text>`;
const arrow=(x,y,a,b,color=C.blue)=>{const ang=Math.atan2(b-y,a-x),s=8;return line(x,y,a,b,color,2.5)+path(`M ${a-s*Math.cos(ang-.5)} ${b-s*Math.sin(ang-.5)} L ${a} ${b} L ${a-s*Math.cos(ang+.5)} ${b-s*Math.sin(ang+.5)}`,'none',color,2.5)};
const many=(n,fn)=>Array.from({length:n},(_,i)=>fn(i)).join('');
const wafer=(x=300,y=170)=>`<ellipse cx="${x}" cy="${y}" rx="110" ry="55" fill="${C.blue}" stroke="${C.ink}" stroke-width="2"/>`+many(7,i=>line(x-78+i*26,y-32,x-78+i*26,y+32,C.pale,1))+many(3,i=>line(x-85,y-26+i*26,x+85,y-26+i*26,C.pale,1));
const base=()=>rect(135,220,330,25);
const label=(zh,a,b)=>zh?a:b;
const EXPLANATIONS={
wafer:['基板與晶粒排列','Substrate and die array','切割間距、平坦度與表面檢查','Kerf, flatness and surface inspection'],polish:['磨盤、載具、晶圓','Platen, carrier and wafer','材料去除與均勻性分開驗證','Separate removal and uniformity evidence'],epitaxy:['晶格延續與界面','Crystal continuity and interface','失配、應變與缺陷需量測','Measure mismatch, strain and defects'],soi:['頂層矽／埋氧／基板','Top Si / buried oxide / handle','分層結構不是厚度規格','Layer structure, not thickness specification'],clean:['清洗、過濾與監測','Cleaning, filtration and monitoring','污染來源與清除路徑需分辨','Separate contamination sources and removal'],fab:['製程模組與回饋','Process modules and feedback','搬運、廠務、製程與量測協同','Coordinate transport, utilities and metrology'],oxide:['爐管與批次晶圓','Furnace tube and wafer batch','氧化成長涉及界面消耗','Oxidation consumes part of the Si interface'],ald:['A／清除／B／清除','A / purge / B / purge','表面反應與飽和需驗證','Verify surface chemistry and saturation'],implant:['離子束與深度分布','Ion beam and depth profile','劑量與能量是不同變數','Dose and energy are distinct variables'],anneal:['熱處理與熱預算','Thermal treatment and budget','溫度歷程影響擴散與活化','Thermal history affects diffusion and activation'],gate:['閘極、隔離、接觸','Gate, isolation and contacts','概念剖面，不代表特定節點','Concept section, not a specific technology node'],nanosheet:['環繞閘極與通道','Surrounding gate and channels','表面界面與電阻共同限制','Interfaces and resistance jointly limit performance'],backside:['正面訊號與背面供電','Front signals and backside power','垂直接觸、對準與熱路徑','Vertical contact, alignment and heat paths'],spin:['旋塗與薄膜分布','Spin coating and film profile','轉速不等於唯一膜厚控制','Speed is not the sole thickness variable'],resist:['曝光與材料反應','Exposure and material response','化學、擴散與隨機性相互影響','Chemistry, diffusion and stochasticity interact'],mask:['設計、光罩與檢查','Design, mask and inspection','圖形補償不是直接複製線寬','Correction is not literal line-width copying'],litho:['光罩、成像、晶圓','Mask, imaging and wafer','解析度與焦深有取捨','Resolution trades off against depth of focus'],pattern:['芯模、間隔層、轉移','Mandrel, spacer and transfer','中間圖形需與最終圖形區分','Distinguish intermediate and final patterns'],etch:['遮罩、側壁與終點','Mask, sidewalls and endpoint','選擇比、深寬比與損傷','Selectivity, aspect ratio and damage'],plasma:['電漿、晶圓與光譜','Plasma, wafer and spectrum','訊號變化需對照製程狀態','Relate signal changes to process state'],cvd:['供氣、反應、排氣','Gas supply, reaction and exhaust','氣相與表面反應共同影響膜','Gas and surface reactions affect the film'],pvd:['靶材、電漿與沉積','Target, plasma and deposition','方向性影響側壁覆蓋','Directionality affects sidewall coverage'],interconnect:['金屬線、通孔與介電層','Lines, vias and dielectric','連通性與阻障完整性','Connectivity and barrier continuity'],cmp:['研磨頭、漿料與平坦化','Carrier, slurry and planarization','局部密度、凹陷與侵蝕','Pattern density, dishing and erosion'],reliability:['加速條件與失效證據','Stress conditions and failure evidence','示意趨勢不是壽命預測','Illustrative trend, not a lifetime prediction'],dram:['電容與存取電晶體','Capacitor and access transistor','保持時間與漏電共同評估','Evaluate retention together with leakage'],nand:['垂直通道與字線層','Vertical channel and word-line layers','圖中層數僅為示意','Layer count is illustrative only'],memory:['材料堆疊與狀態切換','Material stack and state switching','不同記憶體機制不可混用','Different memory mechanisms are not interchangeable'],sensor:['光子、像素與讀出','Photons, pixels and readout','響應、雜訊與串擾需分開','Separate response, noise and crosstalk'],power:['異質材料與端點','Heterogeneous materials and terminals','材料與界面限制需個別分析','Analyze material and interface limits separately'],mems:['懸浮質量、彈簧與電極','Suspended mass, springs and electrodes','慣性結構；壓力器件另看膜片','Inertial structure; pressure devices use diaphragms'],tft:['薄膜通道與閘極','Thin-film channel and gate','基板熱預算與均勻性','Substrate thermal budget and uniformity'],sem:['電子束、掃描與訊號','Electron beam, scan and signal','成像線寬不自動等於真實線寬','Apparent width is not automatically physical width'],optical:['入射、反射與模型','Incidence, reflection and model','光學訊號需反演材料參數','Invert optical signals through a material model'],spc:['抽樣、界限與回饋','Sampling, limits and feedback','管制界限不是規格界限','Control limits are not specification limits'],test:['探針、晶圓與電性','Probe, wafer and electrical response','接觸品質與儀器校準','Contact quality and instrument calibration']};
