   const cb=2>>c,tb=2>>t,out=state.map(()=>[0,0]);
   for(let i=0;i<4;i++){const active=!!(i&cb),j=op.gate==='CX'&&active?i^tb:i;out[j]=op.gate==='CZ'&&active&&(i&tb)?state[i].map(v=>-v):[...state[i]];}state=out;continue;
