 environment:[pair('進料、分離、處理與回收流','feed, separation, treatment and recovery streams'),pair('能耗、污染移轉與回收品質的取捨','energy use, pollutant transfer and recovered-quality trade-offs'),pair('採樣代表性、物料平衡與監測頻率','sampling representativeness, mass balance and monitoring frequency')],
 aerospace:[pair('機體、推進、飛控與航電','airframe, propulsion, flight control and avionics'),pair('重量、疲勞與可維護性的權衡','mass, fatigue and maintainability trade-offs'),pair('公開驗證證據與核准資料的界線','boundaries between public evidence and approved technical data')],
 marine:[pair('船體、浮力、推進與支援系統','hull, buoyancy, propulsion and support systems'),pair('穩性、耐壓與人因的介面','stability, pressure-resistance and human-factor interfaces'),pair('模型假設、海試證據與認證範圍','model assumptions, trial evidence and certification scope')],
