const EXPANSION_CONTEXT_FAMILIES=Object.fromEntries(Object.entries(definitions).map(([id,d])=>[id,{scene:`context-${id}`,name:bi(d[0],d[1]),tool:bi('本領域共用原理示意','Shared domain-principle schematic'),metric:bi(d[6],d[7]),unit:'a.u. / example',min:0,max:Math.max(d[8]*2,4),initial:0,target:d[8],phase:bi('界定邊界 → 追蹤界面 → 核對狀態 → 保留證據','Define boundary → trace interfaces → check state → retain evidence'),observation:[bi(d[2],d[3]),bi(d[4],d[5])]}]));
const C={ink:'#173f38',green:'#5c9975',water:'#9bc8db',blue:'#3979a1',metal:'#d6a74c',rock:'#b5b9a8',red:'#bf655a',paper:'#f4f8ee',pink:'#b695b9'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const path=(d,f='none',stroke=C.ink,w=2,dash='')=>`<path d="${d}" fill="${f}" stroke="${stroke}" stroke-width="${w}"${dash?` stroke-dasharray="${dash}"`:''}/>`;
const rect=(x,y,w,h,f=C.rock,r=0)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${f}" stroke="${C.ink}"/>`;
const txt=(x,y,s,size=10,color=C.ink)=>`<text x="${x}" y="${y}" font-family="system-ui,sans-serif" font-size="${size}" fill="${color}" text-anchor="middle">${esc(s)}</text>`;
const circle=(x,y,r,f=C.paper)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" stroke="${C.ink}"/>`;
const arrow=(x,y,x2,y2,color=C.ink)=>path(`M${x} ${y}L${x2} ${y2}`,'none',color,2)+circle(x2,y2,3,color);
const aliases={barewafer:['a004','separate'],bootchain:['a310','verify'],transformer:['a203','separate'],waterpaths:['b202','two'],railinterfaces:['b301','separate'],waterloop:['b401','branches'],sciencerecords:['c101','r02'],earthobservation:['c307','a'],steelboundary:['d107','split'],ctprojection:['d201','sequence'],resourcenetwork:['d310',null],beamring:['d401','roles']};
/** Deliberately reused domain contexts retain their shared provenance. */
function renderExpansionContext(scene,phase=4,language='en'){
 const id=String(scene).replace(/^context-/,''),t=(zh,en)=>language==='zh'?zh:en;
 if(!EXPANSION_CONTEXT_FAMILIES[id])return '';
 if(aliases[id]){const[cid,expectedChoice]=aliases[id];return `<g data-domain-context="${id}">${renderExpansionScene({expansion:true,courseId:cid,expectedChoice},{output:5,sum:4,gap:2},expectedChoice,phase,language)}</g>`;}
 let out='';
 switch(id){
 case'abrasive':out=rect(55,148,290,64,C.rock)+path('M55 147l20-4 20 5 20-4 20 5 20-4 20 5 20-4 20 5 20-4 20 5 20-4 30 5','none',C.red,2)+rect(71,86,258,31,C.water,8)+[100,147,194,241,288].map(x=>path(`M${x} 139l7-12 7 12z`,C.metal)).join('')+arrow(116,73,281,73)+txt(199,103,t('研磨墊','Pad'))+txt(201,188,'10 − 2 = 8 a.u.')+txt(200,238,t('磨粒／相對運動／殘餘厚度','Abrasive / relative motion / remaining thickness'));break;
 case'insulation':out=rect(57,78,286,136,C.rock,10)+rect(91,103,74,85,C.water,12)+rect(229,103,74,85,C.water,12)+[0,1,2,3].map(i=>rect(103,112+i*17,49,9,C.metal,3)+rect(241,112+i*17,49,9,C.metal,3)).join('')+path('M182 99v96','none',C.pink,8)+txt(124,70,'1: turns')+txt(205,96,'2: main',9)+txt(295,232,'3: enclosure',9)+txt(195,245,t('未通電，非絕緣尺寸圖','De-energized; no insulation dimensions'),9);break;
 case'suspensionbridge':out=path('M27 183h346','none',C.ink,7)+rect(92,80,12,142,C.rock)+rect(296,80,12,142,C.rock)+rect(21,174,29,45,C.rock)+rect(350,174,29,45,C.rock)+path('M36 178Q65 147 98 83Q200 233 302 83Q335 147 364 178','none',C.metal,5)+[[132,125],[166,150],[200,158],[234,150],[268,125]].map(([x,y])=>path(`M${x} ${y}V181`,'none',C.green,2)).join('')+txt(201,67,t('主纜＋垂直吊索','Main cable + vertical hangers'))+txt(201,246,t('錨碇 ← 主纜；橋面 → 吊索','Anchors ← cable; deck → hangers'),10);break;
 case'archdam':out=path('M34 69h57v163H34z',C.rock)+path('M309 69h57v163h-57z',C.rock)+path('M91 132Q200 247 309 132v-23Q200 200 91 109z',C.water)+[126,165,204,243,280].map(x=>arrow(x,81,x,125,C.blue)).join('')+arrow(133,151,87,137,C.red)+arrow(267,151,313,137,C.red)+txt(199,67,t('平面示意：水壓與拱向傳力','Plan: water pressure and arch action'),10)+txt(200,237,t('兩側壩肩＋基礎條件仍須調查','Two abutments + foundation investigation'),10);break;
 case'membrane':out=rect(154,81,79,143,C.water,8)+[164,180,196,212].map(x=>path(`M${x} 89v123`,'none',C.paper,4)).join('')+arrow(34,139,150,139,C.blue)+arrow(235,115,361,115,C.green)+path('M219 201h110','none',C.red,3)+txt(81,120,'Feed 10')+txt(305,95,'Permeate 7')+txt(309,223,'Concentrate 3')+txt(194,246,t('合成水量，品質另驗證','Synthetic flow; quality checked separately'),10);break;
 case'waterquality':out=[73,199,325].map((x,i)=>path(`M${x-23} 101v-23h46v23l15 82q0 24-38 24q-38 0-38-24z`,i===2?C.paper:C.water)+txt(x,147,['✓','✓','?'][i],25,i===2?C.red:C.green)+txt(x,229,['A: record','B: record','C: missing'][i],10)).join('')+txt(200,66,t('透明外觀不等於證據完整','Clear appearance is not complete evidence'),11);break;
 case'radiometry':out=rect(33,88,91,111,C.rock,8)+txt(78,127,'DN = 8',14)+txt(78,160,'synthetic',9)+arrow(129,141,164,141)+path('M182 91h53l30 50-30 50h-53l-29-50z',C.metal)+txt(207,130,'× 0.5',13)+txt(207,157,'+ 1',13)+arrow(266,141,296,141)+rect(301,98,75,89,C.water,8)+txt(340,149,'5 a.u.',14)+txt(199,235,t('係數附屬產品版本；本例不是Landsat係數','Coefficients belong to product version; example only'),9);break;
 case'imagequality':out=[0,1].flatMap(r=>[0,1,2].map(c=>rect(50+c*65,78+r*62,58,54,(r+c)%3===1?C.paper:C.green)+((r+c)%3===1?path(`M${55+c*65} ${82+r*62}l48 44m-48 0 48-44`,'none',C.red):''))).join('')+rect(287,96,65,65,'none')+rect(298,109,65,65,'none')+arrow(292,183,308,173,C.blue)+txt(326,212,t('配準','Register'),10)+txt(142,233,'6 − 2 = 4 valid',12);break;
 case'robotframes':out=rect(45,188,109,24,C.rock)+path('M101 188l61-80 87 43','none',C.water,18)+circle(162,108,14,C.metal)+rect(236,152,105,57,C.rock)+[[63,183,'Base'],[266,167,'Work'],[244,139,'Tool']].map(([x,y,s])=>path(`M${x} ${y}h32m-32 0v-29`,'none',C.red,2)+txt(x+13,y-35,s,9)).join('')+txt(200,241,t('同一點，座標值隨參考框架改變','One point; coordinates depend on reference frame'),10);break;
 case'robotpath':out=path('M44 208h312','none',C.ink,4)+circle(78,191,19,C.rock)+rect(195,114,46,95,C.rock)+path('M105 127Q191 43 301 113','none',C.green,3)+path('M105 127L301 113','none',C.red,2,'5 3')+[ [144,101],[195,85],[247,91] ].map(([x,y],i)=>circle(x,y,8,C.metal)+txt(x,y-13,String(i+1),10)).join('')+txt(201,234,t('端點可達 ≠ 中途無碰撞','Reachable ends ≠ collision-free path'),11);break;
 case'robotstate':out=path('M66 86v58h29v-33h35v33h29V86','none',C.ink,5)+rect(106,120,15,34,C.metal)+arrow(170,119,204,119)+rect(215,91,153,49,C.water,5)+txt(291,121,'Sensor: pending ?',12)+circle(111,202,18,C.green)+txt(111,207,'✓',17)+circle(231,202,18,C.green)+txt(231,207,'✓',17)+path('M131 202h78','none',C.ink,2)+txt(113,241,'Command sent',9)+txt(233,241,'State recorded',9)+txt(288,167,t('尚待夾取確認','Grasp not yet confirmed'),10);break;
 case'reduction':out=path('M164 72h72l12 144h-96z',C.rock)+circle(201,106,13,C.red)+txt(77,88,'Oxide + H₂',12)+arrow(106,102,159,102,C.red)+arrow(244,103,288,103,C.blue)+rect(289,88,48,39,C.water,5)+txt(313,112,'Sep.',10)+arrow(313,88,313,65,C.blue)+txt(348,70,'H₂O',11)+arrow(201,215,201,237,C.metal)+txt(79,194,t('移除氧','Remove oxygen'),11)+txt(284,234,t('海綿鐵 ≠ 完成鋼材','Sponge iron ≠ finished steel'),9)+path('M320 127v50h-70','none',C.blue,2,'4 3')+txt(312,194,t('氣體回收','Gas recycle'),9);break;
 case'hydrogenstorage':out=rect(141,73,117,145,C.water,35)+txt(201,110,'H₂',23)+txt(201,160,'Start 4',12)+txt(201,189,'End 2',12)+arrow(36,133,139,133,C.green)+arrow(260,133,365,133,C.red)+txt(77,115,'Supply 3')+txt(314,115,'Use 5')+txt(201,243,'4 + 3 − 5 = 2 a.u.',12);break;
 case'ctphantom':out=[1,2,3,4].map((n,i)=>rect(110+(i%2)*67,88+Math.floor(i/2)*61,65,59,[C.paper,C.water,C.rock,C.green][i])+txt(142+(i%2)*67,124+Math.floor(i/2)*61,n,20)).join('')+arrow(37,118,100,118,C.red)+arrow(143,65,143,82,C.blue)+txt(299,119,'1 + 2 = 3')+txt(299,181,'3 + 4 = 7')+txt(199,238,t('數位假體；多角度仍需驗證','Digital phantom; multiple views need verification'),10);break;
 case'ctquality':out=rect(29,88,131,129,C.rock,6)+[9,10,11].map((n,i)=>rect(43+i*34,123,31,35,['#a2bdb1','#b4c9b7','#c8dbc6'][i])+txt(59+i*34,145,n,11)).join('')+path('M199 198h171M204 192V76','none',C.ink,2)+[9,10,11].map((n,i)=>circle(237+i*45,176-(n-9)*30,5,C.green)).join('')+path('M221 146h135','none',C.red,2,'4 3')+txt(288,230,'Mean = 10',12)+txt(97,237,t('均勻區樣本','Uniform-region samples'),10);break;
 case'resourcebalance':out=rect(42,93,77,120,C.rock,5)+txt(81,143,'IN 10',13)+path('M119 146h60m0 0h102m-102 0v58h102m-102-58V85h102','none',C.ink,3)+rect(283,65,79,37,C.green,5)+txt(323,89,'Use 7')+rect(283,126,79,38,C.water,5)+txt(322,149,'Stock 1')+rect(283,186,79,37,C.pink,5)+txt(322,210,'Gap 2')+txt(198,243,t('量、品質、時間、責任分別記錄','Record quantity, quality, timing, ownership'),10);break;
 case'resourceresilience':out=circle(68,107,28,C.red)+txt(68,111,'A: stop',10)+circle(68,204,28,C.green)+txt(68,208,'B',13)+circle(319,102,30,C.water)+txt(319,107,'R₁',15)+circle(319,202,30,C.metal)+txt(319,207,'R₂',15)+path('M98 109L289 102M96 117L290 190','none',C.red,2,'5 4')+arrow(99,204,286,204,C.green)+txt(203,238,t('只有R₂仍有獨立來源B','Only R₂ retains independent source B'),11);break;
 case'beamsupport':out=path('M34 170h332v40H34z',C.paper)+path('M39 190h320','none',C.blue,3)+rect(69,151,35,76,C.water,5)+rect(247,151,35,76,C.water,5)+rect(147,160,53,60,C.metal,12)+path('M134 125q12-53 25 0t25 0t25 0','none',C.red,3)+txt(173,74,'RF phase',11)+txt(319,171,'Vacuum',10)+txt(78,246,'Guidance',10)+txt(199,246,'Energy',10)+txt(315,246,'Boundary',10);break;
 case'detectordata':out=circle(69,148,41,C.pink)+circle(69,148,16,C.paper)+path('M29 148h80m-40-40v80','none',C.ink,2)+arrow(113,148,152,148)+[0,1,2].map(i=>rect(168,77+i*52,114,37,i===2?C.paper:C.water,4)+txt(225,100+i*52,['E1 · Cal v2','E2 · Cal v2','E3 · missing'][i],10)).join('')+arrow(285,95,337,95,C.green)+arrow(285,148,337,148,C.green)+path('M298 196l20 20m-20 0 20-20','none',C.red,3)+txt(203,247,t('事件選擇不等於物理結論','Event selection is not a physics conclusion'),10);break;
 }
 return `<g data-domain-context="${id}">${out}</g>`;
}

Object.defineProperty(exports, "EXPANSION_STAGE_FAMILIES", { enumerable: true, get: () => EXPANSION_STAGE_FAMILIES });
Object.defineProperty(exports, "EXPANSION_CONTEXT_FAMILIES", { enumerable: true, get: () => EXPANSION_CONTEXT_FAMILIES });
